22	        String e164 = owner.getTelephone();
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (e164.equals(TelephoneNormalizer.toE164(existing.getTelephone()))) {
25	                throw new DuplicateTelephoneException(e164);
26	            }
27	        }
28	    }
29	}
